278	            <option value="unit">per piece</option>
279	          </select>
280	        </label>
281	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
282	          {NUTRIENT_FIELDS.map((f) => (
283	            <label key={f.key} className="grid gap-1 text-sm">
284	              {f.label} ({f.unit})
285	              <input
286	                className={inputClass(flagged.has(f.key))}
287	                inputMode="decimal"
288	                value={nutrients[f.key]}
289	                onChange={(e) => setNutrients((n) => ({ ...n, [f.key]: e.target.value }))}
290	              />
291	            </label>
292	          ))}
293	        </div>
294	        {basis !== 'unit' && (
295	          <label className="grid max-w-xs gap-1 text-sm">
296	            Serving size ({basis === '100ml' ? 'ml' : 'g'}) <span className="text-muted">optional</span>
297	            <input
298	              className={inputClass(flagged.has('servingSize'))}
