307	      <fieldset>
308	        <legend className="mb-2 text-sm font-semibold">Contains allergens</legend>
309	        <div className="flex flex-wrap gap-2">
310	          {ALLERGENS.map((a) => (
311	            <label
312	              key={a}
313	              className={`flex min-h-11 cursor-pointer items-center gap-2 rounded-full border px-3 text-sm ${
314	                allergens.includes(a) ? 'border-accent bg-accent-soft text-accent' : 'border-line'
315	              }`}
316	            >
317	              <input type="checkbox" className="sr-only" checked={allergens.includes(a)} onChange={() => toggleAllergen(a)} />
318	              <span aria-hidden>{allergens.includes(a) ? '✓' : '+'}</span> {ALLERGEN_LABELS[a]}
319	            </label>
320	          ))}
321	        </div>
322	        <p className="mt-2 text-xs text-muted">Always check product labels for allergens.</p>
323	      </fieldset>
324	
325	      {error && (
326	        <p role="alert" className="rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
327	          {error}
328	        </p>
329	      )}
330	      <div className="flex flex-wrap gap-3">
331	        <Button type="submit" disabled={saving}>
332	          {saving ? 'Saving…' : submitLabel}
333	        </Button>
334	        {onCancel && (
335	          <Button variant="secondary" onClick={onCancel} disabled={saving}>
336	            Cancel
337	          </Button>
338	        )}
339	      </div>
340	    </form>
341	  );
342	}
343	
344	function defaultBasis(unit: DisplayUnit): NutritionBasis {
345	  const d = unitDim(unit);
346	  return d === 'volume' ? '100ml' : d === 'count' ? 'unit' : '100g';
347	}
